CREATE OR REPLACE FUNCTION public.create_sale_order(payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_sale_id uuid;
  v_customer_id uuid;
  v_route_id uuid;
  v_sale_date date;
  v_discount numeric(14,2);
  v_collected numeric(14,2);
  v_note text;
  v_invoice_no text;
  v_gross numeric(14,2) := 0;
  v_net numeric(14,2);
  v_outstanding numeric(14,2);
  v_status text;
  item jsonb;
  v_product_id uuid;
  v_delivered numeric(14,4);
  v_returned numeric(14,4);
  v_sold numeric(14,4);
  v_price numeric(14,2);
begin
  if (select auth.uid()) is null or not private.is_app_member((select auth.uid())) then
    raise exception 'Not authorized for Phuc An Ops';
  end if;

  v_sale_date := coalesce((payload->>'sale_date')::date, current_date);
  v_customer_id := (payload->>'customer_id')::uuid;
  v_route_id := nullif(payload->>'route_id','')::uuid;
  v_discount := greatest(coalesce((payload->>'discount_amount')::numeric,0),0);
  v_collected := greatest(coalesce((payload->>'collected_amount')::numeric,0),0);
  v_note := nullif(payload->>'note','');
  v_invoice_no := nullif(payload->>'invoice_no','');

  if v_customer_id is null then
    raise exception 'customer_id is required';
  end if;

  if jsonb_typeof(payload->'lines') <> 'array' or jsonb_array_length(payload->'lines') = 0 then
    raise exception 'At least one sale line is required';
  end if;

  for item in select value from jsonb_array_elements(payload->'lines')
  loop
    v_product_id := (item->>'product_id')::uuid;
    v_delivered := greatest(coalesce((item->>'qty_delivered')::numeric,0),0);
    v_returned := greatest(coalesce((item->>'qty_returned')::numeric,0),0);
    v_price := greatest(coalesce((item->>'unit_price')::numeric,0),0);
    v_sold := greatest(v_delivered - v_returned,0);

    if v_product_id is null then
      raise exception 'product_id is required on each sale line';
    end if;
    if v_returned > v_delivered then
      raise exception 'qty_returned cannot exceed qty_delivered';
    end if;

    v_gross := v_gross + (v_sold * v_price);
  end loop;

  v_discount := least(v_discount, v_gross);
  v_net := greatest(v_gross - v_discount,0);
  v_collected := least(v_collected, v_net);
  v_outstanding := greatest(v_net - v_collected,0);

  v_status := case
    when v_net = 0 or v_collected >= v_net then 'paid'
    when v_collected > 0 then 'partial'
    else 'unpaid'
  end;

  insert into public.sales(
    sale_date, customer_id, route_id, invoice_no,
    gross_amount, discount_amount, collected_amount, payment_status, note
  ) values (
    v_sale_date, v_customer_id, v_route_id, v_invoice_no,
    v_gross, v_discount, v_collected, v_status, v_note
  )
  returning id into v_sale_id;

  for item in select value from jsonb_array_elements(payload->'lines')
  loop
    v_product_id := (item->>'product_id')::uuid;
    v_delivered := greatest(coalesce((item->>'qty_delivered')::numeric,0),0);
    v_returned := greatest(coalesce((item->>'qty_returned')::numeric,0),0);
    v_price := greatest(coalesce((item->>'unit_price')::numeric,0),0);
    v_sold := greatest(v_delivered - v_returned,0);

    insert into public.sale_items(
      sale_id, product_id, qty, unit_price, discount_pct, qty_delivered, qty_returned
    ) values (
      v_sale_id, v_product_id, v_sold, v_price, 0, v_delivered, v_returned
    );

    if v_returned > 0 then
      insert into public.returns(
        return_date, sale_id, customer_id, route_id, product_id, qty, refund_amount, reason
      ) values (
        v_sale_date, v_sale_id, v_customer_id, v_route_id,
        v_product_id, v_returned, v_returned * v_price, 'Trả cùng đơn bán'
      );
    end if;
  end loop;

  if v_outstanding > 0 then
    insert into public.receivables(
      sale_id, customer_id, amount, paid_amount, status
    ) values (
      v_sale_id, v_customer_id, v_outstanding, 0, 'open'
    );
  end if;

  return v_sale_id;
end;
$function$
